const ITSEC_DOMAINS = ITSEC_LAYERS.map((l, i) => ({ id: "IT" + (i + 1), ja: l.t[0], en: l.t[1] }));

function ItSecOverview({ en, go }) {
  const nSrc = new Set(ITSEC.flatMap((c) => (c.sources || []).map((s) => s.url))).size;
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en ? `AI deployments ride on ordinary enterprise security: endpoints, identity, network and cloud access, data protection, monitoring and governance frameworks. ${ITSEC.length} core concepts, each with what it is, how it works, how it differs from look-alikes, and where it meets AI adoption — tested by ${ITSEC_BANK.length} drills, a mock exam and ${ITSEC_SCEN.length} scenarios, grounded in ${nSrc} public sources (Digital Agency, IPA, MIC, NIST, Microsoft Learn, Google Cloud).`
            : `AI導入は、エンドポイント・ID・ネットワークとクラウドアクセス・データ保護・監視・フレームワークという企業ITのセキュリティの上に乗る。主要${ITSEC.length}概念を「何か・仕組み・似た概念との違い・AI導入との接点」で整理し、${ITSEC_BANK.length}問の判定演習・模試、${ITSEC_SCEN.length}本のシナリオで確かめる。根拠はデジタル庁・IPA・総務省・NIST・Microsoft Learn・Google Cloud の公開資料${nSrc}件。`}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(250px,1fr))", gap: 10, marginBottom: 14 }}>
        {[["diagrams", en ? "Diagrams: ransomware chain, zero trust, SSO, SOC" : "図解：ランサムウェアの連鎖・ゼロトラスト・SSO・SOC", en ? "Plus Japan's reporting clocks and IPA's Top 10 threats" : "国内の報告期限と IPA 10大脅威も"],
          ["incidents", en ? `Incidents in Japan: ${ITSEC_INCIDENTS.length} real cases` : `国内インシデント事例：実例${ITSEC_INCIDENTS.length}件`, en ? "How each worked, causes in three layers and the countermeasure for each" : "仕組み・3層の要因・要因ごとの対策に分解"]].map(([k, t, d]) => (
          <button key={k} onClick={() => go(k)} style={{ textAlign: "left", background: C.surface, border: `1px solid ${C.gold}`, borderRadius: 10, padding: "13px 15px", cursor: "pointer", color: C.text }}>
            <div style={{ fontWeight: 700, fontSize: 14, color: C.gold, marginBottom: 5 }}>{t} →</div>
            <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.55 }}>{d}</div>
          </button>
        ))}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,280px),1fr))", gap: 8, marginBottom: 14 }}>
        {ITSEC_SPLIT.map((s, i) => (
          <div key={i} style={{ background: C.surface2, borderRadius: 10, borderTop: `3px solid ${s.col}`, padding: "10px 12px" }}>
            <div style={{ fontSize: 12.5, fontWeight: 800, color: s.col }}>{s.t[en ? 1 : 0]}</div>
            <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.65, marginTop: 4 }}>{en ? "Where: " : "掲載場所："}{s.where[en ? 1 : 0]}</div>
            <div style={{ fontSize: 11.5, color: C.dim, lineHeight: 1.65, marginTop: 2 }}>{en ? "e.g. " : "例："}{s.eg[en ? 1 : 0]}</div>
          </div>
        ))}
      </div>
      <div style={{ fontSize: 13, fontWeight: 800, color: C.text, margin: "6px 0 8px" }}>{en ? "Eight layers, from the device outward to governance" : "8つの層 — 端末から統治まで"}</div>
      <div style={{ display: "grid", gap: 6 }}>
        {ITSEC_LAYERS.map((l, i) => {
          const cs = ITSEC.filter((c) => c.layer === l.id);
          return (
            <button key={l.id} className="gh-btn" onClick={() => go("glossary", l.id)}
              style={{ display: "flex", gap: 12, alignItems: "baseline", textAlign: "left", borderLeft: `4px solid ${l.col}`, flexWrap: "wrap", padding: "9px 12px" }}>
              <span style={{ fontSize: 11, color: l.col, fontWeight: 800, minWidth: 28 }}>{String(i + 1).padStart(2, "0")}</span>
              <span style={{ minWidth: 150 }}>
                <span style={{ display: "block", fontSize: 13, fontWeight: 800, color: C.text }}>{l.t[en ? 1 : 0]}</span>
                <span style={{ display: "block", fontSize: 11, color: C.dim }}>{l.d[en ? 1 : 0]}</span>
              </span>
              <span style={{ flex: "1 1 260px", fontSize: 11.5, color: C.muted, lineHeight: 1.6 }}>{cs.map((c) => itL(c, "name", en)).join(" ・ ")}</span>
            </button>
          );
        })}
      </div>
      <div style={{ fontSize: 11.5, color: C.dim, lineHeight: 1.7, marginTop: 12 }}>
        {en ? "How to use: read the glossary layer by layer and check look-alike pairs in Compare; test judgment in Drills, Scenarios and the timed mock exam; use Practice for assessment steps and the Issue taxonomy to map technical issues to controls."
            : "使い方：用語解説を層ごとに読み、比較で似た概念の違いを押さえる。判定演習・シナリオ・模試で判断を確かめ、導入・評価の実務で棚卸しから選定までの手順を、論点体系で技術の論点と統制の対応を見る。"}
      </div>
    </div>
  );
}

function ItSecCompare({ en, go }) {
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en ? "The pairs that get confused in proposals and RFPs — each concept's contrast with its nearest look-alike, grouped by layer. Tap a name to open its full entry."
            : "提案書やRFPで取り違えやすい組み合わせ。各概念の「似た概念との違い」を層ごとに並べた。名前を押すと用語解説が開く。"}
      </div>
      {ITSEC_LAYERS.map((l) => {
        const cs = ITSEC.filter((c) => c.layer === l.id && c.diff);
        if (!cs.length) return null;
        return (
          <div key={l.id} style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 12, fontWeight: 800, color: l.col, borderLeft: `3px solid ${l.col}`, paddingLeft: 8, marginBottom: 6 }}>{l.t[en ? 1 : 0]}</div>
            <div style={{ display: "grid", gap: 5 }}>
              {cs.map((c) => (
                <div key={c.id} style={{ display: "flex", gap: 10, background: C.surface2, borderRadius: 8, padding: "7px 11px", flexWrap: "wrap" }}>
                  <button onClick={() => go("glossary", null, c.id)} style={{ all: "unset", cursor: "pointer", fontSize: 12.5, fontWeight: 800, color: C.text, minWidth: 120 }}>{c.name}</button>
                  <span style={{ flex: "1 1 280px", fontSize: 12, color: C.muted, lineHeight: 1.65 }}>{c.diff}</span>
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

function ItSecQuiz({ en }) {
  return <CheckEngine bank={ITSEC_BANK} domains={ITSEC_DOMAINS} storeKey="itsec_stats_v1" noTitle
    intro="広義ITセキュリティの8層の判定問題です。"
    introEn="Judgment questions across eight layers of general IT security. " />;
}

function ItSecPractice({ en }) {
  const jump = (id) => { const c = ITSEC.find((x) => x.id === id); return c ? itL(c, "name", en) : id; };
  return (
    <div>
      <div style={{ fontSize: 12.5, color: C.muted, lineHeight: 1.7, marginBottom: 10 }}>
        {en ? "The working method: how to take stock, measure maturity and gaps, set priorities, check products and vendors, and what to confirm on the general-IT side before bringing in generative AI. Each item names the concepts it rests on."
            : "現状把握から、成熟度とギャップの測り方、優先順位、製品・委託先の確認点、生成AIを入れる前に広義ITで確かめることまでの進め方。各項目に、根拠になる概念を添えた。"}
      </div>
      {ITSEC_PRAC.map((sec, i) => (
        <FoldSection key={i} title={`${i + 1}. ${sec.t[en ? 1 : 0]}`} color={[C.gold, C.teal, C.wine, C.fore, C.muted][i % 5]}>
          <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.7, marginBottom: 8 }}>{sec.lead[en ? 1 : 0]}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(min(100%,300px),1fr))", gap: 8 }}>
            {sec.items.map((it, k) => (
              <div key={k} style={{ background: C.surface2, borderRadius: 10, padding: "10px 12px" }}>
                <div style={{ fontSize: 12.5, fontWeight: 800, color: C.text, marginBottom: 4 }}>{it.t[en ? 1 : 0]}</div>
                <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65 }}>{it.d[en ? 1 : 0]}</div>
                {it.c && it.c.length ? <div style={{ fontSize: 10.5, color: C.dim, marginTop: 6 }}>{en ? "Concepts: " : "関連概念："}{it.c.map(jump).join(" ・ ")}</div> : null}
              </div>
            ))}
          </div>
        </FoldSection>
      ))}
    </div>
  );
}

function ItSecTaxonomy({ en }) {
  if (!ITSEC_TAX.sec.length) return <div style={{ fontSize: 12.5, color: C.muted }}>{en ? "Preparing…" : "準備中…"}</div>;
  const ns = ITSEC_TAX.sec.length, ng = ITSEC_TAX.gov.length;
  const withC = (list) => list.map((x) => ({ ...x, fw: x.fw + (x.c && x.c.length ? (en ? " — concepts: " : " ／ 関連概念：") + x.c.map((id) => itL(ITSEC.find((c) => c.id === id) || { name: id }, "name", en)).join("・") : "") }));
  return <GovTaxonomy en={en} sec={withC(ITSEC_TAX.sec)} gov={withC(ITSEC_TAX.gov)} xref={ITSEC_TAX.xref}
    labels={{ sec: [`技術・脅威の論点 T1〜T${ns}`, `TECHNOLOGY & THREATS — T1-T${ns}`], gov: [`統制・制度の論点 C1〜C${ng}`, `CONTROLS & RULES — C1-C${ng}`],
      intro: [`広義ITセキュリティの論点体系。技術・脅威側（T1〜T${ns}）と統制・制度側（C1〜C${ng}）の2系統で、各論点の中論点・検討すべき問い・参照する概念と規格を示す。下の対応表は、同じテーマを技術と制度の両面から見たときのつながり。`,
        `The issue taxonomy for general IT security in two systems — technology and threats (T1-T${ns}) and controls and rules (C1-C${ng}). Each topic shows its mid-issues, the questions worth asking, and the concepts and standards behind it; the bridge below links the two sides.`] }} />;
}

