// 業界別セクションで各業界見出しの直後に描く、ボックス＋矢印の横型アーキ図。
function ArchFlowFig({ industry, lang }) {
  const en = lang === "en";
  const [sel, setSel] = useState(null);
  const key = Object.keys(ARCH_INDUSTRY_FIG).find((k) => industry && industry.indexOf(k) !== -1);
  const fig = key ? ARCH_INDUSTRY_FIG[key] : null;
  if (!fig || !fig.length) return null;
  const nm = (n) => (en ? (n.labelEn || n.label) : n.label);
  const ds = (n) => (en ? (n.descEn || n.desc) : n.desc);
  const cur = sel != null ? fig[sel] : null;
  return (
    <div style={{ margin: "6px 0 20px", padding: "12px 12px", background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 10 }}>
      <div style={{ fontSize: 10.5, fontWeight: 800, color: C.gold, letterSpacing: ".1em", marginBottom: 10 }}>{en ? "REFERENCE ARCHITECTURE" : "リファレンス・アーキテクチャ"}</div>
      <div className="gh-figscroll" style={{ display: "flex", alignItems: "stretch", flexWrap: "nowrap", gap: 6, paddingBottom: 2 }}>
        {fig.map((n, j) => {
          const on = sel === j;
          return (
          <div key={j} style={{ display: "flex", alignItems: "center", gap: 6, flexShrink: 0 }}>
            <div role="button" tabIndex={0} aria-pressed={on}
                 onClick={() => setSel(on ? null : j)}
                 onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setSel(on ? null : j); } }}
                 style={{ width: 152, background: on ? C.bg : C.surface, border: `1px solid ${on ? C.gold : C.line}`, borderRadius: 8, padding: "8px 9px", cursor: "pointer",
                          boxShadow: on ? `0 0 0 1px ${C.gold}` : "none", opacity: sel != null && !on ? 0.62 : 1 }}>
              <div style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 4 }}>
                <span style={{ flexShrink: 0, width: 16, height: 16, borderRadius: "50%", background: C.gold, color: "#1a1204", fontSize: 9.5, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center" }}>{j + 1}</span>
                <span style={{ fontSize: 11.5, fontWeight: 800, color: C.text, lineHeight: 1.2 }}>{nm(n)}</span>
              </div>
              <div style={{ fontSize: 10, color: C.muted, lineHeight: 1.45 }}>{ds(n)}</div>
            </div>
            {j < fig.length - 1 ? <span style={{ color: C.gold, fontSize: 16, fontWeight: 700 }}>→</span> : null}
          </div>
          );
        })}
      </div>
      {cur ? (
        <div style={{ marginTop: 10, background: C.bg, border: `1px solid ${C.line}`, borderLeft: `3px solid ${C.gold}`, borderRadius: 8, padding: "9px 11px" }}>
          <div style={{ fontSize: 12.5, fontWeight: 800, color: C.gold }}>
            {sel + 1}/{fig.length}　{nm(cur)}<span style={{ fontSize: 10.5, color: C.muted, fontWeight: 500, marginLeft: 6 }}>{en ? cur.label : (cur.labelEn || "")}</span>
          </div>
          <div style={{ fontSize: 12, color: C.text, lineHeight: 1.7, marginTop: 4 }}>{ds(cur)}</div>
          <div style={{ fontSize: 10.5, color: C.muted, marginTop: 6 }}>
            {sel > 0 ? `${en ? "From" : "前の工程"}：${nm(fig[sel - 1])}` : (en ? "Start of the flow" : "この流れの起点")}
            {"　/　"}
            {sel < fig.length - 1 ? `${en ? "To" : "次の工程"}：${nm(fig[sel + 1])}` : (en ? "End of the flow" : "この流れの終点")}
          </div>
        </div>
      ) : (
        <div style={{ fontSize: 10.5, color: C.dim, marginTop: 8 }}>
          {en ? "Tap a stage to read it full-size and see what comes before and after." : "工程をタップすると、説明を大きく読めて前後のつながりも出ます。"}
        </div>
      )}
    </div>
  );
}
function ArchBlocks({ blocks, lang, sectionId }) {
  const en = lang === "en";
  const L = (ja, e) => (en ? e : ja);
  // 業界別セクションでは、各業界（h見出し）配下の連続リストにカテゴリ見出しを付ける
  const INDUSTRY_CATS = [["ユースケース", "Use cases"], ["制約・規制", "Constraints & regulation"], ["アーキ勘所", "Architecture keys"]];
  const catOf = {};
  if (sectionId === "industry") {
    let li = 0;
    (blocks || []).forEach((b, idx) => {
      if (b.t === "h") li = 0;
      else if (b.t === "list" && !b.ordered) { if (INDUSTRY_CATS[li]) catOf[idx] = INDUSTRY_CATS[li]; li++; }
    });
  }
  // 演習ブロックに演習順のindexを割り当てる（ARCH_EXERCISE_STEPS 参照用）
  const exOf = {};
  { let eo = 0; (blocks || []).forEach((b, idx) => { if (b.t === "exercise") { exOf[idx] = eo; eo++; } }); }
  const renderBlock = (b, i) => {
        if (b.t === "h") return (
          <div key={i}>
            <h3 style={{ fontSize: 15, fontWeight: 800, color: C.gold, margin: "20px 0 8px" }}>{L(b.ja, b.en)}</h3>
            {sectionId === "industry" ? <ArchFlowFig industry={b.ja} lang={lang} /> : null}
          </div>
        );
        if (b.t === "p") return <p key={i} style={{ fontSize: 13, lineHeight: 1.9, color: C.text, margin: "0 0 10px" }}>{L(b.ja, b.en)}</p>;
        if (b.t === "list") {
          const items = b.items || [];
          if (b.ordered) return <ol key={i} style={{ margin: "0 0 12px", paddingLeft: 22 }}>{items.map((it, j) => <li key={j} style={{ fontSize: 12.5, lineHeight: 1.8, color: C.text, marginBottom: 4 }}>{L(it.ja, it.en)}</li>)}</ol>;
          // 「ラベル：説明」形式が大半の箇条書きは、番号つきステージカードの縦型パイプライン図として描画する
          const parsed = items.map((it) => { const s = L(it.ja, it.en); const m = s.match(/^([^：:]{1,30})[：:]\s*([\s\S]+)$/); return { label: m ? m[1].trim() : null, desc: m ? m[2].trim() : s }; });
          const labelled = parsed.filter((p) => p.label).length;
          if (items.length >= 3 && labelled / items.length >= 0.7) {
            return (
              <div key={i} style={{ margin: "8px 0 16px" }}>
                {parsed.map((p, j) => (
                  <div key={j}>
                    <div style={{ display: "flex", gap: 10, alignItems: "flex-start", background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 10, padding: "10px 12px" }}>
                      <span style={{ flexShrink: 0, width: 24, height: 24, borderRadius: "50%", background: C.gold, color: "#1a1204", fontSize: 12, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 1 }}>{j + 1}</span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        {p.label ? <div style={{ fontSize: 13, fontWeight: 800, color: C.gold, marginBottom: 2 }}>{p.label}</div> : null}
                        <div style={{ fontSize: 12, color: C.text, lineHeight: 1.7 }}>{p.desc}</div>
                      </div>
                    </div>
                    {j < parsed.length - 1 ? <div style={{ textAlign: "center", color: C.teal, fontSize: 13, lineHeight: 1, margin: "3px 0" }}>▼</div> : null}
                  </div>
                ))}
              </div>
            );
          }
          // 3件以上の列挙（コロンなし）は、アクセントつきカードグリッドで視覚化する
          if (items.length >= 3) {
            const cat = catOf[i];
            return (
              <div key={i} style={{ margin: "10px 0 16px" }}>
                {cat ? <div style={{ fontSize: 11.5, fontWeight: 800, color: C.teal, letterSpacing: ".06em", margin: "0 0 8px", borderLeft: `3px solid ${C.teal}`, paddingLeft: 8, lineHeight: 1.3 }}>{L(cat[0], cat[1])}</div> : null}
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(min(100%,240px),1fr))", gap: 8 }}>
                  {items.map((it, j) => (
                    <div key={j} style={{ display: "flex", gap: 9, alignItems: "flex-start", background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 9, padding: "9px 11px" }}>
                      <span style={{ flexShrink: 0, width: 19, height: 19, borderRadius: "50%", background: C.teal, color: "#08201c", fontSize: 10.5, fontWeight: 800, display: "flex", alignItems: "center", justifyContent: "center", marginTop: 1 }}>{j + 1}</span>
                      <span style={{ fontSize: 12, color: C.text, lineHeight: 1.6 }}>{L(it.ja, it.en)}</span>
                    </div>
                  ))}
                </div>
              </div>
            );
          }
          return <ul key={i} style={{ margin: "0 0 12px", paddingLeft: 22 }}>{items.map((it, j) => <li key={j} style={{ fontSize: 12.5, lineHeight: 1.8, color: C.text, marginBottom: 4 }}>{L(it.ja, it.en)}</li>)}</ul>;
        }
        if (b.t === "callout") {
          const col = b.kind === "warn" ? C.wine : (b.kind === "tip" ? C.teal : C.gold);
          return <div key={i} style={{ margin: "12px 0", padding: "10px 14px", borderLeft: `3px solid ${col}`, background: C.surface2, borderRadius: 8, fontSize: 12.5, lineHeight: 1.75, color: C.text }}>{L(b.ja, b.en)}</div>;
        }
        if (b.t === "cards") {
          return <div key={i} style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(220px,1fr))", gap: 10, margin: "6px 0 14px" }}>
            {(b.cards || []).map((c, j) => <div key={j} style={{ background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 10, padding: "12px 14px" }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.gold, marginBottom: 5 }}>{L(c.hJa, c.hEn)}</div>
              <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.7 }}>{L(c.bJa, c.bEn)}</div>
            </div>)}
          </div>;
        }
        if (b.t === "table") {
          return <div key={i} style={{ margin: "6px 0 16px", overflowX: "auto" }}>
            {(b.titleJa || b.titleEn) ? <div style={{ fontSize: 12.5, fontWeight: 700, color: C.text, marginBottom: 6 }}>{L(b.titleJa, b.titleEn)}</div> : null}
            <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320, fontSize: 12 }}>
              <thead><tr>{(b.cols || []).map((c, j) => <th key={j} style={{ textAlign: "left", padding: "7px 10px", background: C.surface2, color: C.gold, border: `1px solid ${C.line}`, fontWeight: 700 }}>{L(c.ja, c.en)}</th>)}</tr></thead>
              <tbody>{(b.rows || []).map((r, ri) => <tr key={ri}>{r.map((cell, ci) => <td key={ci} style={{ padding: "7px 10px", border: `1px solid ${C.line}`, color: C.text, lineHeight: 1.65, verticalAlign: "top" }}>{L(cell.ja, cell.en)}</td>)}</tr>)}</tbody>
            </table>
          </div>;
        }
        if (b.t === "steps") {
          return <div key={i} style={{ margin: "6px 0 14px" }}>
            {(b.steps || []).map((s, j) => <div key={j} style={{ display: "flex", gap: 12, marginBottom: 12 }}>
              <div style={{ flexShrink: 0, width: 26, height: 26, borderRadius: "50%", background: C.wine, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12 }}>{j + 1}</div>
              <div><div style={{ fontSize: 13, fontWeight: 700, color: C.text }}>{L(s.ja, s.en)}</div>{(s.descJa || s.descEn) ? <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.75, marginTop: 2 }}>{L(s.descJa, s.descEn)}</div> : null}</div>
            </div>)}
          </div>;
        }
        if (b.t === "tree") {
          return <div key={i} style={{ margin: "8px 0 16px", padding: "12px 14px", background: C.surface2, border: `1px solid ${C.line}`, borderRadius: 10 }}>
            <div style={{ fontSize: 11, color: C.dim, marginBottom: 8 }}>{L("クリックで展開/折りたたみ", "Click to expand/collapse")}</div>
            <ArchTree node={en ? b.en : b.ja} />
          </div>;
        }
        if (b.t === "exercise") return <ArchExercise key={i} b={b} lang={lang} idx={exOf[i]} />;
        return null;
  };
  const all = blocks || [];
  // 見出しが2つ以上ある節は、見出しごとに折りたたむ（最初は閉じる）。見出しが1つの節（演習）はそのまま並べる
  if (all.filter((b) => b.t === "h").length < 2) return <div>{all.map(renderBlock)}</div>;
  const parts = []; let cur = null;
  all.forEach((b, i) => {
    if (b.t === "h") { cur = { i, b, kids: [] }; parts.push(cur); }
    else if (cur) cur.kids.push(renderBlock(b, i));
    else parts.push({ el: renderBlock(b, i) });
  });
  return (
    <div>
      {parts.map((p) => (p.b ? (
        <FoldSection key={"h" + p.i} id={"arch-" + sectionId + "-" + p.b.ja} color={C.gold} title={L(p.b.ja, p.b.en)}>
          {sectionId === "industry" ? <ArchFlowFig industry={p.b.ja} lang={lang} /> : null}
          {p.kids}
        </FoldSection>
      ) : p.el))}
    </div>
  );
}
